import { Pool, type PoolClient } from 'pg';
import bcrypt from 'bcryptjs';

process.loadEnvFile();
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

async function insertMany(tx: PoolClient, table: string, columns: string[], rows: Record<string, unknown>[]): Promise<number[]> {
  const ids: number[] = [];
  for (const row of rows) {
    const cols = columns.join(', ');
    const placeholders = columns.map((_, i) => `$${i + 1}`).join(', ');
    const values = columns.map(c => row[c]);
    const res = await tx.query(`INSERT INTO ${table} (${cols}) VALUES (${placeholders}) RETURNING id`, values);
    ids.push(Number(res.rows[0].id));
  }
  return ids;
}

